module mst_calculator (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [31:0] x0, y0, z0,\n    input wire [31:0] x1, y1, z1,\n    input wire [31:0] x2, y2, z2,\n    input wire [31:0] x3, y3, z3,\n    input wire [31:0] x4, y4, z4,\n    input wire [31:0] x5, y5, z5,\n    input wire [31:0] x6, y6, z6,\n    input wire [31:0] x7, y7, z7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    parameter MAX_N = 8;\n    parameter DATA_WIDTH = 32;\n    parameter INF = 32'h7FFF_FFFF;\n\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] INIT_DIST   = 4'd1;\n    localparam [3:0] FIND_MIN    = 4'd2;\n    localparam [3:0] ADD_TO_TREE = 4'd3;\n    localparam [3:0] UPDATE_DIST = 4'd4;\n    localparam [3:0] DONE_STATE  = 4'd5;\n    localparam [3:0] COST_WAIT   = 4'd6;\n\n    reg [DATA_WIDTH-1:0] x_reg [0:MAX_N-1];\n    reg [DATA_WIDTH-1:0] y_reg [0:MAX_N-1];\n    reg [DATA_WIDTH-1:0] z_reg [0:MAX_N-1];\n    reg loaded;\n\n    reg [3:0] state, next_state;\n    reg [MAX_N-1:0] visited, next_visited;\n    reg [DATA_WIDTH-1:0] dist [0:MAX_N-1];\n    reg [DATA_WIDTH-1:0] next_dist [0:MAX_N-1];\n    reg [DATA_WIDTH-1:0] total_cost, next_total_cost;\n    reg [3:0] curr_planet, next_curr_planet;\n    reg [3:0] visited_count, next_visited_count;\n    reg [3:0] init_i, next_init_i;\n    reg [3:0] find_j, next_find_j;\n    reg [3:0] update_k, next_update_k;\n\n    reg cost_compute_start, next_cost_compute_start;\n    reg [3:0] i_idx, next_i_idx;\n    reg [3:0] j_idx, next_j_idx;\n    reg [DATA_WIDTH-1:0] cost_out, next_cost_out;\n    reg cost_valid, next_cost_valid;\n    reg [1:0] cost_state, next_cost_state;\n\n    reg [2:0] idx, next_idx;\n    reg [DATA_WIDTH-1:0] temp_dx, temp_dy, temp_dz;\n\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            loaded <= 1'b0;\n            for (i = 0; i < MAX_N; i = i + 1) begin\n                x_reg[i] <= 32'd0;\n                y_reg[i] <= 32'd0;\n                z_reg[i] <= 32'd0;\n            end\n        end else if (start) begin\n            x_reg[0] <= x0; y_reg[0] <= y0; z_reg[0] <= z0;\n            x_reg[1] <= x1; y_reg[1] <= y1; z_reg[1] <= z1;\n            x_reg[2] <= x2; y_reg[2] <= y2; z_reg[2] <= z2;\n            x_reg[3] <= x3; y_reg[3] <= y3; z_reg[3] <= z3;\n            x_reg[4] <= x4; y_reg[4] <= y4; z_reg[4] <= z4;\n            x_reg[5] <= x5; y_reg[5] <= y5; z_reg[5] <= z5;\n            x_reg[6] <= x6; y_reg[6] <= y6; z_reg[6] <= z6;\n            x_reg[7] <= x7; y_reg[7] <= y7; z_reg[7] <= z7;\n            loaded <= 1'b1;\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            cost_out <= 32'd0;\n            cost_valid <= 1'b0;\n            cost_state <= 2'd0;\n        end else begin\n            case (cost_state)\n                2'd0: begin\n                    cost_valid <= 1'b0;\n                    if (cost_compute_start) begin\n                        temp_dx <= (x_reg[i_idx] > x_reg[j_idx]) ? x_reg[i_idx] - x_reg[j_idx] : x_reg[j_idx] - x_reg[i_idx];\n                        temp_dy <= (y_reg[i_idx] > y_reg[j_idx]) ? y_reg[i_idx] - y_reg[j_idx] : y_reg[j_idx] - y_reg[i_idx];\n                        temp_dz <= (z_reg[i_idx] > z_reg[j_idx]) ? z_reg[i_idx] - z_reg[j_idx] : z_reg[j_idx] - z_reg[i_idx];\n                        next_cost_state <= 2'd1;\n                    end\n                end\n                2'd1: begin\n                    cost_out <= (temp_dx < temp_dy) ? ((temp_dx < temp_dz) ? temp_dx : temp_dz) : ((temp_dy < temp_dz) ? temp_dy : temp_dz);\n                    cost_valid <= 1'b1;\n                    next_cost_state <= 2'd0;\n                end\n                default: next_cost_state <= 2'd0;\n            endcase\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            visited <= 8'd0;\n            total_cost <= 32'd0;\n            curr_planet <= 4'd0;\n            visited_count <= 4'd0;\n            init_i <= 4'd0;\n            find_j <= 4'd0;\n            update_k <= 4'd0;\n            cost_compute_start <= 1'b0;\n            i_idx <= 4'd0;\n            j_idx <= 4'd0;\n            idx <= 3'd0;\n            done <= 1'b0;\n            for (i = 0; i < MAX_N; i = i + 1) begin\n                dist[i] <= INF;\n            end\n        end else begin\n            state <= next_state;\n            visited <= next_visited;\n            total_cost <= next_total_cost;\n            curr_planet <= next_curr_planet;\n            visited_count <= next_visited_count;\n            init_i <= next_init_i;\n            find_j <= next_find_j;\n            update_k <= next_update_k;\n            cost_compute_start <= next_cost_compute_start;\n            i_idx <= next_i_idx;\n            j_idx <= next_j_idx;\n            idx <= next_idx;\n            if (state == DONE_STATE) done <= 1'b1;\n            else done <= 1'b0;\n            for (i = 0; i < MAX_N; i = i + 1) begin\n                dist[i] <= next_dist[i];\n            end\n        end\n    end\n\n    always @(*) begin\n        next_state = state;\n        next_visited = visited;\n        next_total_cost = total_cost;\n        next_curr_planet = curr_planet;\n        next_visited_count = visited_count;\n        next_init_i = init_i;\n        next_find_j = find_j;\n        next_update_k = update_k;\n        next_cost_compute_start = 1'b0;\n        next_i_idx = i_idx;\n        next_j_idx = j_idx;\n        next_idx = idx;\n        for (i = 0; i < MAX_N; i = i + 1) begin\n            next_dist[i] = dist[i];\n        end\n\n        case (state)\n            IDLE: begin\n                if (start && loaded) begin\n                    next_total_cost = 32'd0;\n                    next_visited = 8'b0000_0001;\n                    next_visited_count = 4'd1;\n                    next_curr_planet = 4'd0;\n                    for (i = 1; i < MAX_N; i = i + 1) begin\n                        next_dist[i] = INF;\n                    end\n                    next_state = (N == 4'd1) ? DONE_STATE : INIT_DIST;\n                    next_init_i = 4'd1;\n                end\n            end\n\n            INIT_DIST: begin\n                next_i_idx = 4'd0;\n                next_j_idx = init_i;\n                next_cost_compute_start = 1'b1;\n                next_idx = 3'd0;\n                next_state = COST_WAIT;\n            end\n\n            COST_WAIT: begin\n                if (cost_valid) begin\n                    if (idx != 3'd0) begin\n                        if (cost_out < next_dist[update_k]) begin\n                            next_dist[update_k] = cost_out;\n                        end\n                        next_update_k = update_k + 4'd1;\n                        next_state = UPDATE_DIST;\n                    end else begin\n                        next_dist[init_i] = cost_out;\n                        if (init_i < N - 4'd1) begin\n                            next_init_i = init_i + 4'd1;\n                            next_state = INIT_DIST;\n                        end else begin\n                            next_state = FIND_MIN;\n                            next_find_j = 4'd0;\n                            next_total_cost = INF;\n                        end\n                    end\n                end\n            end\n\n            FIND_MIN: begin\n                if (find_j < N) begin\n                    if (!visited[find_j]) begin\n                        if (dist[find_j] < next_total_cost) begin\n                            next_total_cost = dist[find_j];\n                            next_curr_planet = find_j;\n                        end\n                    end\n                    next_find_j = find_j + 4'd1;\n                end else begin\n                    next_visited[curr_planet] = 1'b1;\n                    next_visited_count = visited_count + 4'd1;\n                    next_total_cost = total_cost + dist[curr_planet];\n                    next_state = ADD_TO_TREE;\n                end\n            end\n\n            ADD_TO_TREE: begin\n                next_find_j = 4'd0;\n                next_update_k = 4'd0;\n                next_state = UPDATE_DIST;\n            end\n\n            UPDATE_DIST: begin\n                if (update_k < N) begin\n                    if (!visited[update_k]) begin\n                        next_i_idx = curr_planet;\n                        next_j_idx = update_k;\n                        next_cost_compute_start = 1'b1;\n                        next_idx = 3'd1;\n                        next_state = COST_WAIT;\n                    end else begin\n                        next_update_k = update_k + 4'd1;\n                    end\n                end else begin\n                    if (visited_count == N) begin\n                        next_state = DONE_STATE;\n                    end else begin\n                        next_find_j = 4'd0;\n                        next_total_cost = INF;\n                        next_state = FIND_MIN;\n                    end\n                end\n            end\n\n            DONE_STATE: begin\n                next_state = IDLE;\n            end\n\n            default: next_state = IDLE;\n        endcase\n    end\nendmodule